11	export type WebauthnSessionPayload = {
12	  uid: string;
13	  email: string;
14	  iat: number;
15	  exp: number;
16	  webauthn: true;
17	};
18	
19	/**
20	 * Sign a WebAuthn/OTP session payload with the dedicated
21	 * SESSION_SIGNING_SECRET (Security F1). Never falls back to a hardcoded
22	 * literal or CRON_SECRET: getSessionSigningSecret() throws if the secret is
23	 * unset, so callers fail closed rather than issuing an unsigned or
24	 * trivially-forgeable cookie. Used by the OTP verify route; the WebAuthn
25	 * login route (apps/web/src/app/api/auth/webauthn/login/route.ts, not owned
26	 * by this change) still signs independently with the old
27	 * `CRON_SECRET ?? "webauthn-session-secret"` pattern and needs to be
28	 * switched to this helper — see the handoff note in the auth-hardening
29	 * report.
30	 */
31	export function signWebauthnSession(
32	  payload: Pick<WebauthnSessionPayload, "uid" | "email">
33	): string {
34	  const fullPayload: WebauthnSessionPayload = {
35	    uid: payload.uid,
36	    email: payload.email,
37	    iat: Math.floor(Date.now() / 1000),
38	    exp: Math.floor(Date.now() / 1000) + SESSION_MAX_AGE_SECONDS,
39	    webauthn: true,
40	  };
41	  const payloadStr = JSON.stringify(fullPayload);
42	  const secret = getSessionSigningSecret();
43	  const sig = createHmac("sha256", secret).update(payloadStr).digest("base64url");
44	  return `webauthn.${Buffer.from(payloadStr).toString("base64url")}.${sig}`;
45	}
