286	async function buildAuthContext(dbUser: typeof users.$inferSelect): Promise<AuthContext> {
287	  const memberships = await db
288	    .select({
289	      tenantId: tenantMemberships.tenantId,
290	      membershipCategory: tenantMemberships.membershipCategory,
291	      status: tenantMemberships.status,
292	      roleType: adminAssignments.roleType,
293	      permissions: adminAssignments.permissions,
294	    })
295	    .from(tenantMemberships)
296	    .leftJoin(
297	      adminAssignments,
298	      eq(tenantMemberships.userId, adminAssignments.userId)
299	    )
300	    .where(eq(tenantMemberships.userId, dbUser.id));
301	
302	  return {
303	    user: {
304	      id: dbUser.id,
305	      firebaseUid: dbUser.firebaseUid,
306	      email: dbUser.email,
307	      firstName: dbUser.firstName,
308	      lastName: dbUser.lastName,
309	      phone: dbUser.phone,
310	    },
311	    memberships: memberships.map((m) => ({
312	      tenantId: m.tenantId,
313	      membershipCategory: m.membershipCategory,
314	      status: m.status,
315	      role: m.roleType
316	        ? { roleType: m.roleType, permissions: m.permissions ?? [] }
317	        : null,
318	    })),
319	  };
320	}
