import { NextRequest, NextResponse } from "next/server";
import { cookies } from "next/headers";
import { AuditEntityType, AuditAction } from "@accessbuddy/shared";

const SESSION_COOKIE_NAME = "session";
const SESSION_MAX_AGE = 60 * 60 * 24 * 14; // 14 days

export async function POST(request: NextRequest) {
  try {
    const { idToken } = await request.json();
    if (!idToken) {
      return NextResponse.json({ error: "Token required" }, { status: 400 });
    }

    const hasServiceAccount = !!process.env.FIREBASE_SERVICE_ACCOUNT_KEY;

    let sessionValue: string;

    if (hasServiceAccount) {
      // Production: create a proper session cookie via Firebase Admin
      const { getAdminAuth } = await import("@/lib/firebase-admin");
      const adminAuth = getAdminAuth();
      sessionValue = await adminAuth.createSessionCookie(idToken, {
        expiresIn: SESSION_MAX_AGE * 1000,
      });
    } else {
      // Dev: store the ID token directly as the session cookie
      sessionValue = idToken;
    }

    const cookieStore = await cookies();
    cookieStore.set(SESSION_COOKIE_NAME, sessionValue, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: SESSION_MAX_AGE,
    });

    // Build redirect hints: check admin assignments and memberships
    let isAdmin = false;
    let tenantSlug: string | null = null;
    let membershipCount = 0;
    try {
      const { db } = await import("@accessbuddy/db");
      const { users, adminAssignments, tenants, tenantMemberships } = await import("@accessbuddy/db");
      const { eq } = await import("drizzle-orm");

      // Decode the token to get the email
      let email: string | null = null;
      if (hasServiceAccount) {
        const { getAdminAuth } = await import("@/lib/firebase-admin");
        const decoded = await getAdminAuth().verifyIdToken(idToken);
        email = decoded.email ?? null;
      } else {
        // Dev mode: decode JWT payload
        const payload = JSON.parse(Buffer.from(idToken.split(".")[1], "base64").toString());
        email = payload.email ?? null;
      }

      if (email) {
        const [user] = await db.select({ id: users.id }).from(users).where(eq(users.email, email)).limit(1);
        if (user) {
          // Check admin assignments first (admin wins)
          let adminTenantId: string | null = null;
          const [admin] = await db
            .select({ tenantId: adminAssignments.tenantId })
            .from(adminAssignments)
            .where(eq(adminAssignments.userId, user.id))
            .limit(1);
          if (admin && admin.tenantId) {
            adminTenantId = admin.tenantId;
            const [t] = await db.select({ slug: tenants.slug }).from(tenants).where(eq(tenants.id, admin.tenantId)).limit(1);
            if (t) {
              isAdmin = true;
              tenantSlug = t.slug;
            }
          } else if (admin && !admin.tenantId) {
            // Global admin - find first tenant
            const [t] = await db.select({ id: tenants.id, slug: tenants.slug }).from(tenants).limit(1);
            if (t) {
              isAdmin = true;
              tenantSlug = t.slug;
              adminTenantId = t.id;
            }
          }

          // Check memberships for non-admin routing
          const memberships = await db
            .select({ tenantId: tenantMemberships.tenantId })
            .from(tenantMemberships)
            .where(eq(tenantMemberships.userId, user.id));
          membershipCount = memberships.length;

          // If not admin but has memberships, set tenantSlug for routing
          if (!isAdmin && membershipCount > 0) {
            const [t] = await db
              .select({ slug: tenants.slug })
              .from(tenants)
              .where(eq(tenants.id, memberships[0].tenantId))
              .limit(1);
            if (t) tenantSlug = t.slug;
          }

          // Record login in audit log (fire-and-forget, don't block login)
          const { getClientIp } = await import("@/lib/rate-limit");
          const { createAuditEntry } = await import("@/lib/services/audit");
          const ip = getClientIp(request);
          createAuditEntry(db, {
            tenantId: adminTenantId ?? memberships[0]?.tenantId ?? null,
            entityType: AuditEntityType.MEMBER,
            entityId: user.id,
            action: AuditAction.LOGIN,
            actorId: user.id,
            actorType: "user",
            metadata: { email },
            ipAddress: ip === "unknown" ? null : ip,
          }).catch(() => {});
        }
      }
    } catch {
      // Non-critical - just won't auto-route
    }

    return NextResponse.json({ success: true, isAdmin, tenantSlug, membershipCount });
  } catch (err) {
    console.error("Session creation error:", err);
    return NextResponse.json({ error: "Failed to create session" }, { status: 401 });
  }
}

export async function DELETE() {
  const cookieStore = await cookies();
  cookieStore.delete(SESSION_COOKIE_NAME);
  return NextResponse.json({ success: true });
}

