import { eq } from "drizzle-orm";
import { users } from "@accessbuddy/db";
import { AuditEntityType } from "@accessbuddy/shared";
import { getAdminAuth } from "@/lib/firebase-admin";
import { clientEnv } from "@/env";
import {
  sendTemplatedEmail,
  type EmailSendResult,
  type TenantEmailConfig,
} from "@/lib/services/email";
import { withTenant } from "@/lib/with-tenant";

/**
 * Generate a Firebase magic link and send it via Resend.
 *
 * Shared by the global (/api/auth/send-magic-link) and
 * tenant-scoped (/api/v1/t/[slug]/auth/send-magic-link) endpoints.
 *
 * When a tenantId is supplied, the email send is wrapped in a withTenant
 * block so the audit entry can be written under tenant RLS context.
 */
export async function generateAndSendMagicLink(params: {
  email: string;
  redirect: string;
  clubName: string;
  emailConfig: TenantEmailConfig;
  tenantId?: string;
}): Promise<EmailSendResult> {
  const { email, redirect, clubName, tenantId } = params;
  // Magic link emails are auth-critical — bypass the tenant sendEmails flag.
  const emailConfig = { ...params.emailConfig, sendEmails: true };
  const appUrl = clientEnv.NEXT_PUBLIC_APP_URL;

  const actionCodeSettings = {
    url: `${appUrl}/auth/callback?redirect=${encodeURIComponent(redirect)}`,
    handleCodeInApp: true,
  };

  const adminAuth = getAdminAuth();
  const magicLink = await adminAuth.generateSignInWithEmailLink(
    email,
    actionCodeSettings
  );

  const memberName = email.split("@")[0];

  if (tenantId) {
    return withTenant(tenantId, async (tx) => {
      // Resolve the user id (if any) so the audit entry can be linked to the
      // member record. If there is no user row yet we skip audit — the
      // sign-up flow will create one.
      const [user] = await tx
        .select({ id: users.id })
        .from(users)
        .where(eq(users.email, email))
        .limit(1);

      return sendTemplatedEmail(
        email,
        "magicLink",
        { memberName, magicLinkUrl: magicLink },
        emailConfig,
        undefined,
        user
          ? {
              tx,
              tenantId,
              entityType: AuditEntityType.MEMBER,
              entityId: user.id,
              actorId: null,
            }
          : undefined
      );
    });
  }

  // Global magic link flow: no tenant context, no audit entry possible.
  return sendTemplatedEmail(
    email,
    "magicLink",
    { memberName, magicLinkUrl: magicLink },
    emailConfig
  );
}

