1	import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
2	import { db } from "@accessbuddy/db";
3	import { otpCodes } from "@accessbuddy/db/src/schema/auth-tokens";
4	import { and, desc, eq, isNull } from "drizzle-orm";
5	
6	/**
7	 * Durable, hashed, single-use OTP store backed by Postgres (`otp_codes`).
8	 *
9	 * Replaces the previous module-level in-memory Map, which lost all codes on
10	 * Cloud Run scale-out / cold start (the PWA's only sign-in path). Codes are
11	 * never stored in plaintext, are single-use (consumed on first successful
12	 * verification), and are capped at MAX_ATTEMPTS wrong guesses.
13	 *
14	 * NOT tenant-scoped: keyed on email pre-auth. See the note in
15	 * packages/db/src/schema/auth-tokens.ts — this table must not get RLS
16	 * tenant policies.
17	 */
18	
19	const OTP_TTL_MS = 5 * 60 * 1000;
20	const MAX_ATTEMPTS = 5;
21	const SCRYPT_KEYLEN = 64;
22	
23	export type VerifyOtpResult = "valid" | "invalid" | "expired" | "locked";
24	
25	function normalizeEmail(email: string): string {
26	  return email.toLowerCase().trim();
27	}
28	
29	function hashCode(code: string, salt: string): string {
30	  return scryptSync(code, salt, SCRYPT_KEYLEN).toString("hex");
31	}
32	
33	/**
34	 * Generate and persist a new OTP for `email`. Any prior unconsumed codes for
35	 * the same email are invalidated first so only the most recently sent code
36	 * is ever valid.
37	 */
38	export async function setOtp(email: string, code: string): Promise<void> {
39	  const normalizedEmail = normalizeEmail(email);
40	  const salt = randomBytes(16).toString("hex");
41	  const codeHash = `${salt}:${hashCode(code, salt)}`;
42	  const expiresAt = new Date(Date.now() + OTP_TTL_MS);
43	
44	  await db
45	    .delete(otpCodes)
46	    .where(and(eq(otpCodes.email, normalizedEmail), isNull(otpCodes.consumedAt)));
47	
48	  await db.insert(otpCodes).values({ email: normalizedEmail, codeHash, expiresAt });
49	}
50	
51	/**
52	 * Verify `code` for `email`. On success the code is atomically marked
53	 * consumed (single-use). On failure the attempt counter is incremented;
54	 * once it reaches MAX_ATTEMPTS the code is locked out regardless of further
55	 * guesses, even if they happen to be correct.
56	 */
57	export async function verifyOtp(email: string, code: string): Promise<VerifyOtpResult> {
58	  const normalizedEmail = normalizeEmail(email);
59	
60	  const [entry] = await db
61	    .select()
62	    .from(otpCodes)
63	    .where(and(eq(otpCodes.email, normalizedEmail), isNull(otpCodes.consumedAt)))
64	    .orderBy(desc(otpCodes.createdAt))
65	    .limit(1);
66	
67	  if (!entry) return "invalid";
68	  if (entry.expiresAt.getTime() < Date.now()) return "expired";
69	  if (entry.attempts >= MAX_ATTEMPTS) return "locked";
70	
71	  const [salt, storedHash] = entry.codeHash.split(":");
72	  const candidateHash = hashCode(code, salt);
73	
74	  const matches =
75	    storedHash.length === candidateHash.length &&
76	    timingSafeEqual(Buffer.from(storedHash, "hex"), Buffer.from(candidateHash, "hex"));
77	
78	  if (!matches) {
79	    await db
80	      .update(otpCodes)
81	      .set({ attempts: entry.attempts + 1 })
82	      .where(eq(otpCodes.id, entry.id));
83	    return "invalid";
84	  }
85	
86	  await db
87	    .update(otpCodes)
88	    .set({ consumedAt: new Date() })
89	    .where(eq(otpCodes.id, entry.id));
90	  return "valid";
91	}
92

