import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
import { db } from "@accessbuddy/db";
import { otpCodes } from "@accessbuddy/db/src/schema/auth-tokens";
import { and, desc, eq, isNull } from "drizzle-orm";

/**
 * Durable, hashed, single-use OTP store backed by Postgres (`otp_codes`).
 *
 * Replaces the previous module-level in-memory Map, which lost all codes on
 * Cloud Run scale-out / cold start (the PWA's only sign-in path). Codes are
 * never stored in plaintext, are single-use (consumed on first successful
 * verification), and are capped at MAX_ATTEMPTS wrong guesses.
 *
 * NOT tenant-scoped: keyed on email pre-auth. See the note in
 * packages/db/src/schema/auth-tokens.ts — this table must not get RLS
 * tenant policies.
 */

const OTP_TTL_MS = 5 * 60 * 1000;
const MAX_ATTEMPTS = 5;
const SCRYPT_KEYLEN = 64;

export type VerifyOtpResult = "valid" | "invalid" | "expired" | "locked";

function normalizeEmail(email: string): string {
  return email.toLowerCase().trim();
}

function hashCode(code: string, salt: string): string {
  return scryptSync(code, salt, SCRYPT_KEYLEN).toString("hex");
}

/**
 * Generate and persist a new OTP for `email`. Any prior unconsumed codes for
 * the same email are invalidated first so only the most recently sent code
 * is ever valid.
 */
export async function setOtp(email: string, code: string): Promise<void> {
  const normalizedEmail = normalizeEmail(email);
  const salt = randomBytes(16).toString("hex");
  const codeHash = `${salt}:${hashCode(code, salt)}`;
  const expiresAt = new Date(Date.now() + OTP_TTL_MS);

  await db
    .delete(otpCodes)
    .where(and(eq(otpCodes.email, normalizedEmail), isNull(otpCodes.consumedAt)));

  await db.insert(otpCodes).values({ email: normalizedEmail, codeHash, expiresAt });
}

/**
 * Verify `code` for `email`. On success the code is atomically marked
 * consumed (single-use). On failure the attempt counter is incremented;
 * once it reaches MAX_ATTEMPTS the code is locked out regardless of further
 * guesses, even if they happen to be correct.
 */
export async function verifyOtp(email: string, code: string): Promise<VerifyOtpResult> {
  const normalizedEmail = normalizeEmail(email);

  const [entry] = await db
    .select()
    .from(otpCodes)
    .where(and(eq(otpCodes.email, normalizedEmail), isNull(otpCodes.consumedAt)))
    .orderBy(desc(otpCodes.createdAt))
    .limit(1);

  if (!entry) return "invalid";
  if (entry.expiresAt.getTime() < Date.now()) return "expired";
  if (entry.attempts >= MAX_ATTEMPTS) return "locked";

  const [salt, storedHash] = entry.codeHash.split(":");
  const candidateHash = hashCode(code, salt);

  const matches =
    storedHash.length === candidateHash.length &&
    timingSafeEqual(Buffer.from(storedHash, "hex"), Buffer.from(candidateHash, "hex"));

  if (!matches) {
    await db
      .update(otpCodes)
      .set({ attempts: entry.attempts + 1 })
      .where(eq(otpCodes.id, entry.id));
    return "invalid";
  }

  await db
    .update(otpCodes)
    .set({ consumedAt: new Date() })
    .where(eq(otpCodes.id, entry.id));
  return "valid";
}

