1	import { createHmac, timingSafeEqual } from "node:crypto";
2	import { db } from "@accessbuddy/db";
3	import { users, tenantMemberships, adminAssignments, tenants, fobRequests } from "@accessbuddy/db";
4	import { eq, and, isNull } from "drizzle-orm";
5	import { AdminRoleType } from "@accessbuddy/shared";
6	import { getSessionSigningSecret } from "@/env";
7	
8	/** Shared session lifetime for WebAuthn/OTP-signed session cookies. */
9	export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 14; // 14 days
10	
11	export type WebauthnSessionPayload = {
12	  uid: string;
13	  email: string;
14	  iat: number;
15	  exp: number;
16	  webauthn: true;
17	};
18	
19	/**
20	 * Sign a WebAuthn/OTP session payload with the dedicated
21	 * SESSION_SIGNING_SECRET (Security F1). Never falls back to a hardcoded
22	 * literal or CRON_SECRET: getSessionSigningSecret() throws if the secret is
23	 * unset, so callers fail closed rather than issuing an unsigned or
24	 * trivially-forgeable cookie. Used by the OTP verify route; the WebAuthn
25	 * login route (apps/web/src/app/api/auth/webauthn/login/route.ts, not owned
26	 * by this change) still signs independently with the old
27	 * `CRON_SECRET ?? "webauthn-session-secret"` pattern and needs to be
28	 * switched to this helper — see the handoff note in the auth-hardening
29	 * report.
30	 */
31	export function signWebauthnSession(
32	  payload: Pick<WebauthnSessionPayload, "uid" | "email">
33	): string {
34	  const fullPayload: WebauthnSessionPayload = {
35	    uid: payload.uid,
36	    email: payload.email,
37	    iat: Math.floor(Date.now() / 1000),
38	    exp: Math.floor(Date.now() / 1000) + SESSION_MAX_AGE_SECONDS,
39	    webauthn: true,
40	  };
41	  const payloadStr = JSON.stringify(fullPayload);
42	  const secret = getSessionSigningSecret();
43	  const sig = createHmac("sha256", secret).update(payloadStr).digest("base64url");
44	  return `webauthn.${Buffer.from(payloadStr).toString("base64url")}.${sig}`;
45	}
46	
47	export type VerifiedWebauthnSession = { uid: string; email: string };
48	
49	/**
50	 * Verify a `webauthn.<payload>.<sig>` session cookie value and return its
51	 * `{ uid, email }`, or `null` if the signature is missing, forged,
52	 * malformed, or the token is expired.
53	 *
54	 * Extracted from getAuthUser as a standalone pure(ish) function so it is
55	 * unit-testable without a Next.js request context (next/headers' cookies()
56	 * throws outside one). Signature and expiry verification are unconditional
57	 * (Security F1) — there is no code path here that skips them.
58	 */
59	export function verifyWebauthnSessionCookie(cookieValue: string): VerifiedWebauthnSession | null {
60	  const parts = cookieValue.split(".");
61	  if (parts.length !== 3 || parts[0] !== "webauthn") return null;
62	
63	  const payloadStr = Buffer.from(parts[1], "base64url").toString();
64	  let payload: Record<string, unknown>;
65	  try {
66	    payload = JSON.parse(payloadStr);
67	  } catch {
68	    return null;
69	  }
70	
71	  // getSessionSigningSecret() throws if SESSION_SIGNING_SECRET is unset or
72	  // too short — never fall back to a literal or to CRON_SECRET. Callers
73	  // (getAuthUser) catch this and treat it as unauthenticated: fail closed.
74	  const secret = getSessionSigningSecret();
75	  const expectedSig = createHmac("sha256", secret).update(payloadStr).digest("base64url");
76	  const providedSig = parts[2];
77	  const sigValid =
78	    providedSig.length === expectedSig.length &&
79	    timingSafeEqual(Buffer.from(providedSig), Buffer.from(expectedSig));
80	  if (!sigValid) return null;
81	
82	  const exp = typeof payload.exp === "number" ? payload.exp : null;
83	  if (!exp || exp < Math.floor(Date.now() / 1000)) return null;
84	
85	  const uid =
86	    (typeof payload.uid === "string" && payload.uid) ||
87	    (typeof payload.sub === "string" && payload.sub) ||
88	    "";
89	  if (!uid) return null;
90	  const email = typeof payload.email === "string" ? payload.email.toLowerCase().trim() : "";
91	
92	  return { uid, email };
93	}
94	
95	export type AuthUser = {
96	  id: string;
97	  firebaseUid: string;
98	  email: string;
99	  firstName: string;
100	  lastName: string;
101	  phone: string | null;
102	};
103	
104	export type TenantMembership = {
105	  tenantId: string;
106	  membershipCategory: string | null;
107	  status: string;
108	  role: {
109	    roleType: string;
110	    permissions: string[];
111	  } | null;
112	};
113	
114	export type AuthContext = {
115	  user: AuthUser;
116	  memberships: TenantMembership[];
117	};
118	
119	/**
120	 * Check if the authenticated user has global admin privileges.
121	 */
122	export function isGlobalAdmin(auth: AuthContext | null): boolean {
123	  return auth?.memberships.some(
124	    (m) => m.role?.roleType === AdminRoleType.GLOBAL_ADMIN
125	  ) ?? false;
126	}
127	
128	const firebaseEnabled = !!process.env.NEXT_PUBLIC_FIREBASE_API_KEY;
129	
130	/**
131	 * Get the current authenticated user. Creates a DB record on first visit.
132	 * Returns null if not authenticated.
133	 */
134	export async function getAuthUser(): Promise<AuthContext | null> {
135	  // Check dev login cookie (gated on NODE_ENV + ENABLE_DEV_LOGIN, never Host)
136	  const devEmail = await getDevLoginEmail();
137	  if (devEmail) {
138	    return getDevUserByEmail(devEmail);
139	  }
140	
141	  if (!firebaseEnabled) {
142	    // Security F4: fail closed. A build/runtime missing
143	    // NEXT_PUBLIC_FIREBASE_API_KEY must never grant unauthenticated
144	    // global-admin access. The dev-user bypass is only permitted outside
145	    // production, and only when dev login is explicitly enabled.
146	    if (process.env.NODE_ENV === "production" || !isDevLoginEnabled()) {
147	      return null;
148	    }
149	    return getDevUser();
150	  }
151	
152	  // Verify session cookie (Firebase or WebAuthn)
153	  const sessionCookie = await getSessionCookie();
154	  if (!sessionCookie) return null;
155	
156	  try {
157	    let uid: string;
158	    let email: string;
159	    let displayName: string;
160	
161	    const hasServiceAccount = !!process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
162	
163	    if (sessionCookie.startsWith("webauthn.")) {
164	      // WebAuthn/OTP session. Signature verification is unconditional
165	      // (Security F1) — it must never be skippable via an unrelated env
166	      // var (previously gated on `hasServiceAccount`). A missing
167	      // SESSION_SIGNING_SECRET throws inside getSessionSigningSecret()
168	      // (called from verifyWebauthnSessionCookie), which is caught below
169	      // and treated as unauthenticated: fail closed.
170	      const verified = verifyWebauthnSessionCookie(sessionCookie);
171	      if (!verified) return null;
172	
173	      uid = verified.uid;
174	      email = verified.email;
175	      displayName = "";
176	    } else if (hasServiceAccount) {
177	      // Production: verify Firebase session cookie
178	      const { getAdminAuth } = await import("@/lib/firebase-admin");
179	      const adminAuth = getAdminAuth();
180	      const decoded = await adminAuth.verifySessionCookie(sessionCookie, true);
181	      uid = decoded.uid;
182	      email = (decoded.email ?? "").toLowerCase().trim();
183	      displayName = decoded.name ?? "";
184	    } else if (process.env.NODE_ENV !== "production") {
185	      // Dev only: decode the ID token JWT payload without verification.
186	      // Guarded on NODE_ENV so a production deploy that is missing
187	      // FIREBASE_SERVICE_ACCOUNT_KEY cannot fall back to trusting an
188	      // unverified client-supplied token (same fail-closed principle as F4).
189	      const parts = sessionCookie.split(".");
190	      if (parts.length !== 3) return null;
191	      const payload = JSON.parse(Buffer.from(parts[1], "base64url").toString());
192	      uid = payload.user_id ?? payload.sub ?? "";
193	      email = (payload.email ?? "").toLowerCase().trim();
194	      displayName = payload.name ?? "";
195	    } else {
196	      // Production with no service account and no recognised session
197	      // format: fail closed rather than trusting an unverified token.
198	      return null;
199	    }
200	
201	    if (!uid) return null;
202	
203	    // Find or create user
204	    let [dbUser] = await db
205	      .select()
206	      .from(users)
207	      .where(eq(users.firebaseUid, uid))
208	      .limit(1);
209	
210	    if (!dbUser && email) {
211	      // Check by email in case user was created before signing up
212	      [dbUser] = await db
213	        .select()
214	        .from(users)
215	        .where(eq(users.email, email))
216	        .limit(1);
217	
218	      if (dbUser) {
219	        // Link existing user to Firebase account
220	        [dbUser] = await db
221	          .update(users)
222	          .set({
223	            firebaseUid: uid,
224	            firstName: displayName.split(" ")[0] || dbUser.firstName,
225	            lastName: displayName.split(" ").slice(1).join(" ") || dbUser.lastName,
226	          })
227	          .where(eq(users.id, dbUser.id))
228	          .returning();
229	      } else {
230	        // Create new user
231	        const nameParts = displayName.split(" ");
232	        [dbUser] = await db
233	          .insert(users)
234	          .values({
235	            firebaseUid: uid,
236	            email,
