13	/**
14	 * Build an Error from a failed auth-email response, preferring the server's
15	 * member-facing message (e.g. "We could not send your sign-in link right
16	 * now...") over the generic fallback.
17	 */
18	async function errorFromResponse(res: Response, fallback: string): Promise<Error> {
19	  const data = await res.json().catch(() => null);
20	  return new Error(data?.error ?? fallback);
21	}
22	
23	function isPwa(): boolean {
24	  if (typeof window === "undefined") return false;
25	  return window.matchMedia("(display-mode: standalone)").matches
26	    || ("standalone" in window.navigator && (window.navigator as { standalone?: boolean }).standalone === true);
27	}
28	
29	export function SignInForm() {
30	  const searchParams = useSearchParams();
31	  const router = useRouter();
32	  const redirectTo = safeRedirect(searchParams.get("redirect"));
33	  const [email, setEmail] = useState("");
34	  const [loading, setLoading] = useState(false);
35	  const [sent, setSent] = useState(false);
36	  const [error, setError] = useState<string | null>(null);
37	  const [resent, setResent] = useState(false);
38	  const [resendCooldown, setResendCooldown] = useState(false);
39	  const [passkeyAvailable, setPasskeyAvailable] = useState(false);
40	  const [passkeyLoading, setPasskeyLoading] = useState(false);
41	  const [standaloneMode, setStandaloneMode] = useState(false);
42	  const [otpCode, setOtpCode] = useState("");
43	  const [otpSent, setOtpSent] = useState(false);
44	
45	  useEffect(() => {
46	    if (typeof window === "undefined") return;
47	    setStandaloneMode(isPwa());
48	    if (browserSupportsWebAuthn() && localStorage.getItem("passkey_prompted") === "true") {
49	      setPasskeyAvailable(true);
50	    }
51	  }, []);
52	
53	  async function handlePasskeyLogin() {
54	    setPasskeyLoading(true);
55	    setError(null);
56	    try {
