"use client";

import { useEffect, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Card, CardContent } from "@/components/ui/card";
import { safeRedirect } from "@/lib/safe-redirect";

export function AuthCallback() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const redirectTo = safeRedirect(searchParams.get("redirect"));
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function completeSignIn() {
      try {
        const { auth } = await import("@/lib/firebase");
        const { isSignInWithEmailLink, signInWithEmailLink } = await import("firebase/auth");

        if (!isSignInWithEmailLink(auth, window.location.href)) {
          setError("Invalid sign-in link.");
          return;
        }

        let email = window.localStorage.getItem("emailForSignIn");
        if (!email) {
          email = window.prompt("Please enter your email to confirm sign-in:");
          if (!email) {
            setError("Email required to complete sign-in.");
            return;
          }
        }

        const result = await signInWithEmailLink(auth, email, window.location.href);
        window.localStorage.removeItem("emailForSignIn");

        const idToken = await result.user.getIdToken();
        const res = await fetch("/api/auth/session", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ idToken }),
        });

        if (!res.ok) {
          throw new Error("Failed to create session");
        }

        // Auto-route to the right dashboard after sign-in.
        // If the user was heading somewhere specific (e.g., deep link from
        // their club), honour that. Otherwise route based on permissions:
        //   admin → admin dashboard
        //   single membership → member dashboard
        //   multiple memberships → clubs selector
        const isGenericRedirect =
          redirectTo === "/" || redirectTo === "/clubs" || redirectTo.endsWith("/dashboard");

        try {
          const sessionData = await res.json();
          if (isGenericRedirect && sessionData.tenantSlug) {
            if (sessionData.isAdmin) {
              router.replace(`/t/${sessionData.tenantSlug}/admin`);
              return;
            }
            if (sessionData.membershipCount === 1) {
              router.replace(`/t/${sessionData.tenantSlug}/dashboard`);
              return;
            }
            // Multiple memberships — let them pick
            if (sessionData.membershipCount > 1) {
              router.replace("/clubs");
              return;
            }
          }
        } catch {
          // JSON parse failed — fall through to redirect param
        }

        router.replace(redirectTo);
      } catch (err) {
        console.error("Auth callback error:", err);
        setError("Sign-in failed. The link may have expired. Please try again.");
      }
    }

    completeSignIn();
  }, [router, redirectTo]);

  return (
    <Card className="w-full max-w-sm">
      <CardContent className="py-8 text-center">
        {error ? (
          <div className="space-y-3">
            <p className="text-sm text-destructive">{error}</p>
            <a href="/sign-in" className="text-sm text-primary hover:underline">
              Back to sign-in
            </a>
          </div>
        ) : (
          <div className="space-y-2">
            <div className="mx-auto h-8 w-8 animate-spin rounded-full border-2 border-primary border-t-transparent" />
            <p className="text-sm text-muted-foreground">Completing sign-in...</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

