import { NextResponse } from "next/server";
import { timingSafeEqual } from "node:crypto";

/**
 * Shared auth gate for cron endpoints (Cloud Scheduler → x-cron-secret).
 *
 * Fails closed: if CRON_SECRET is unset or empty the endpoint must not run
 * (503), and the provided header is compared timing-safely (401 on
 * mismatch). Returns null when the request is authorised.
 *
 * Usage:
 *   const unauthorised = requireCronSecret(request, "daily");
 *   if (unauthorised) return unauthorised;
 */
export function requireCronSecret(
  request: Request,
  routeName: string
): NextResponse | null {
  const cronSecret = process.env.CRON_SECRET;
  if (!cronSecret) {
    console.error(`Cron ${routeName} invoked but CRON_SECRET is not configured`);
    return NextResponse.json({ error: "Service misconfigured" }, { status: 503 });
  }

  const provided = request.headers.get("x-cron-secret") ?? "";
  const providedBuf = Buffer.from(provided);
  const expectedBuf = Buffer.from(cronSecret);
  if (
    providedBuf.length !== expectedBuf.length ||
    !timingSafeEqual(providedBuf, expectedBuf)
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  return null;
}

/**
 * Validates a `redirect` query-param value before it is used to navigate
 * the browser, to close an open-redirect that would otherwise fire at the
 * highest-trust moment available: immediately post-authentication.
 *
 * Only accepts a same-origin, root-relative path. Rejects and falls back
 * to `fallback` for anything that could resolve off-origin:
 * - values that do not start with "/" (e.g. "https://evil.example")
 * - protocol-relative values starting with "//" (the browser treats
 *   "//evil.example" as "https://evil.example" when embedded in a URL)
 * - values containing a backslash (some browsers normalise "/\evil.example"
 *   to "//evil.example", a classic bypass for a naive "//" check)
 */
export function safeRedirect(
  value: string | null | undefined,
  fallback = "/"
): string {
  if (!value) return fallback;
  if (!value.startsWith("/")) return fallback;
  if (value.startsWith("//")) return fallback;
  if (value.includes("\\")) return fallback;
  return value;
}

