8	export function AuthCallback() {
9	  const router = useRouter();
10	  const searchParams = useSearchParams();
11	  const redirectTo = safeRedirect(searchParams.get("redirect"));
12	  const [error, setError] = useState<string | null>(null);
13	
14	  useEffect(() => {
15	    async function completeSignIn() {
16	      try {
17	        const { auth } = await import("@/lib/firebase");
18	        const { isSignInWithEmailLink, signInWithEmailLink } = await import("firebase/auth");
19	
20	        if (!isSignInWithEmailLink(auth, window.location.href)) {
21	          setError("Invalid sign-in link.");
22	          return;
23	        }
24	
25	        let email = window.localStorage.getItem("emailForSignIn");
26	        if (!email) {
27	          email = window.prompt("Please enter your email to confirm sign-in:");
28	          if (!email) {
29	            setError("Email required to complete sign-in.");
30	            return;
31	          }
32	        }
33	
34	        const result = await signInWithEmailLink(auth, email, window.location.href);
35	        window.localStorage.removeItem("emailForSignIn");
36	
37	        const idToken = await result.user.getIdToken();
38	        const res = await fetch("/api/auth/session", {
39	          method: "POST",
40	          headers: { "Content-Type": "application/json" },
41	          body: JSON.stringify({ idToken }),
42	        });
43	
44	        if (!res.ok) {
45	          throw new Error("Failed to create session");
46	        }
47	
48	        // Auto-route to the right dashboard after sign-in.
49	        // If the user was heading somewhere specific (e.g., deep link from
50	        // their club), honour that. Otherwise route based on permissions:
51	        //   admin → admin dashboard
52	        //   single membership → member dashboard
53	        //   multiple memberships → clubs selector
54	        const isGenericRedirect =
55	          redirectTo === "/" || redirectTo === "/clubs" || redirectTo.endsWith("/dashboard");
56	
57	        try {
58	          const sessionData = await res.json();
59	          if (isGenericRedirect && sessionData.tenantSlug) {
60	            if (sessionData.isAdmin) {
61	              router.replace(`/t/${sessionData.tenantSlug}/admin`);
62	              return;
63	            }
64	            if (sessionData.membershipCount === 1) {
65	              router.replace(`/t/${sessionData.tenantSlug}/dashboard`);
66	              return;
67	            }
68	            // Multiple memberships — let them pick
69	            if (sessionData.membershipCount > 1) {
70	              router.replace("/clubs");
71	              return;
72	            }
73	          }
74	        } catch {
75	          // JSON parse failed — fall through to redirect param
76	        }
77	
78	        router.replace(redirectTo);
79	      } catch (err) {
80	        console.error("Auth callback error:", err);
81	        setError("Sign-in failed. The link may have expired. Please try again.");
82	      }
83	    }
84	
85	    completeSignIn();
86	  }, [router, redirectTo]);
87	
88	  return (
89	    <Card className="w-full max-w-sm">
90	      <CardContent className="py-8 text-center">
91	        {error ? (
92	          <div className="space-y-3">
93	            <p className="text-sm text-destructive">{error}</p>
94	            <a href="/sign-in" className="text-sm text-primary hover:underline">
95	              Back to sign-in
96	            </a>
97	          </div>
98	        ) : (
99	          <div className="space-y-2">
100	            <div className="mx-auto h-8 w-8 animate-spin rounded-full border-2 border-primary border-t-transparent" />
101	            <p className="text-sm text-muted-foreground">Completing sign-in...</p>
102	          </div>
103	        )}
104	      </CardContent>
105	    </Card>
106	  );
107	}
