17	    adminApp = initializeApp({ credential: cert(serviceAccount) });
18	  } else if (projectId) {
19	    // On GCP, uses Application Default Credentials
20	    adminApp = initializeApp({ projectId });
21	  } else {
22	    // Dev mode without Firebase - admin app won't be used
23	    adminApp = initializeApp({ projectId: "demo-accessbuddy" });
24	  }
25	  return adminApp;
26	}
