4	/**
5	 * Shared auth gate for cron endpoints (Cloud Scheduler → x-cron-secret).
6	 *
7	 * Fails closed: if CRON_SECRET is unset or empty the endpoint must not run
8	 * (503), and the provided header is compared timing-safely (401 on
9	 * mismatch). Returns null when the request is authorised.
10	 *
11	 * Usage:
12	 *   const unauthorised = requireCronSecret(request, "daily");
13	 *   if (unauthorised) return unauthorised;
14	 */
15	export function requireCronSecret(
16	  request: Request,
17	  routeName: string
18	): NextResponse | null {
19	  const cronSecret = process.env.CRON_SECRET;
20	  if (!cronSecret) {
21	    console.error(`Cron ${routeName} invoked but CRON_SECRET is not configured`);
22	    return NextResponse.json({ error: "Service misconfigured" }, { status: 503 });
23	  }
24	
25	  const provided = request.headers.get("x-cron-secret") ?? "";
26	  const providedBuf = Buffer.from(provided);
27	  const expectedBuf = Buffer.from(cronSecret);
28	  if (
29	    providedBuf.length !== expectedBuf.length ||
30	    !timingSafeEqual(providedBuf, expectedBuf)
31	  ) {
32	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
33	  }
34	
35	  return null;
36	}
