echo "== email link"; curl -s -X PATCH -H "$H" -H "$Q" -H "$J" "https://identitytoolkit.googleapis.com/admin/v2/projects/$PID/config?updateMask=signIn.email,authorizedDomains" -d "{\"signIn\":{\"email\":{\"enabled\":true,\"passwordRequired\":false}},\"authorizedDomains\":[\"localhost\",\"$PID.firebaseapp.com\",\"$PID.web.app\",\"nicholaswood.com.au\"]}" | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps({k:d.get(k) for k in (\"signIn\",\"authorizedDomains\",\"error\")}))"; sleep 15;
echo "== web app"; curl -s -X POST -H "$H" -H "$Q" -H "$J" "https://firebase.googleapis.com/v1beta1/projects/$PID/webApps" -d "{\"displayName\":\"LSV Service Summary\"}" | head -c 200; echo; sleep 10;
APP=$(curl -s -H "$H" -H "$Q" "https://firebase.googleapis.com/v1beta1/projects/$PID/webApps" | python3 -c "import sys,json; d=json.load(sys.stdin); print(d.get(\"apps\",[{}])[0].get(\"appId\",\"\"))"); echo "appId=$APP";
