  const out: Record<string, DayForecast[]> = {};
  for (const area of areas(xml, type)) {
    const name = String(area["@_description"]);
    const days: DayForecast[] = [];
    for (const p of periods(area)) {
      const forecast = textOf(p, "forecast");
      const d: DayForecast = { date: localDate(String(p["@_start-time-local"])), forecast };
      if (forecast) Object.assign(d, stripUndefined(extractFromText(forecast)));
      const fd = textOf(p, "fire_danger");
      if (fd) d.fireDanger = fd;
      const uvAlert = textOf(p, "uv_alert");
      if (uvAlert && !d.uv) d.uv = extractFromText(uvAlert).uv ?? uvAlert;
      days.push(d);
    }
    out[name] = mergeSameDay(days);
  }
