  const precis = parsePrecis(xml.townPrecis);
  const text = parseText(xml.townText, "location");
  const towns: Record<string, DayForecast[]> = {};
  for (const [name, days] of Object.entries(precis)) {
    const textDays = new Map((text[name] ?? []).map((d) => [d.date, d]));
    towns[name] = days.map((d) => ({ ...d, ...stripUndefined(textDays.get(d.date) ?? { date: d.date }) }));
  }
  return {
    format: "lsv-bom-weather",
    issued: issued.local,
    issuedUtc: issued.utc,
    fetchedAt: fetchedAt.toISOString(),
